-- Enable UUID extension
create extension if not exists "uuid-ossp";

-- 1. Account Holders
create table account_holders (
  profile_id text primary key,
  first_name text not null,
  last_name text not null,
  email text,
  phone text,
  address text,
  city text,
  state text,
  zip_code text,
  plan_type text,
  signature_base64 text
);

-- 2. Inventory Items
create table inventory_items (
  item_id text primary key,
  device_name text,
  category text,
  brand text,
  model text,
  serial_number text,
  scanlily_url text,
  scanlily_flag text,
  equipment_status text,
  last_scanned_at timestamp with time zone default now()
);

-- 3. Claims
create table claims (
  claim_id uuid default uuid_generate_v4() primary key,
  item_id text references inventory_items(item_id),
  profile_id text references account_holders(profile_id),
  provider_claim_id text, -- The ID generated by the insurance system
  filing_date date default current_date,
  failure_date date,
  description text,
  status text default 'draft',
  pdf_url text,
  created_at timestamp with time zone default now()
);

